INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1850, 'declaration', 'ˌdɛkləˈreɪʃən', 'noun', '{"zh-TW":["宣告；聲明","申報"],"en":["an official statement","a formal announcement"]}', NULL, 'customs declaration/declaration of intent', '[{"en":"Please complete the customs declaration form.","zh-TW":"請填寫海關申報表。"}]', '{"verb":"declare","adjective":"declarative","adverb":"declaratively"}', NULL, 4, 1850, 964),
(1851, 'declarative', '/dɪˈklærətɪv/', 'adjective', '{"zh-TW":["聲明性的；宣示的"],"en":["relating to a formal declaration; describing what should be done rather than how"]}', NULL, 'declarative statement / declarative programming / declarative knowledge', '[{"en":"Declarative programming specifies what the program should accomplish.","zh-TW":"聲明性程式設計指定程序應該完成什麼。"},{"en":"The treaty includes a declarative commitment to reduce emissions.","zh-TW":"條約包括減少排放的聲明性承諾。"}]', '{"adverb":"declaratively"}', NULL, 4, 1851, NULL),
(1852, 'declare', '/dɪˈkleər/', 'verb', '{"zh-TW":["申報；宣告"],"en":["to announce officially or formally"]}', NULL, 'declare bankruptcy / declare a dividend / declare income', '[{"en":"The company declared a special dividend of 50 cents per share.","zh-TW":"公司宣佈發放每股50分的特別股利。"},{"en":"All income must be declared on the annual tax return.","zh-TW":"所有收入必須在年度納稅申報表上申報。"}]', '{"noun":"declaration","adjective":"declared"}', NULL, 3, 1852, NULL),
(1853, 'decline', '/dɪˈklaɪn/', 'verb / noun', '{"zh-TW":["下降；拒絕"],"en":["to decrease in quantity or importance; to politely refuse","to decrease","to politely refuse"]}', '{"prefix":{"text":"de-","meaning":"down (向下)"},"root":{"text":"cline","meaning":"lean (傾斜)"},"logic":"向下傾斜，即「下降」。"}', 'decline an offer/invitation; decline an invitation / sharp decline / decline in', '[{"en":"Sales have declined by 10% this quarter.","zh-TW":"本季度銷售額下降了10%。"},{"en":"She declined the job offer.","zh-TW":"她拒絕了工作邀請。"},{"en":"Sales have declined by 10% this quarter.","zh-TW":"本季銷售額下降了10%。"},{"en":"She politely declined the invitation.","zh-TW":"她禮貌地拒絕了邀請。"}]', '{"noun":"decline","verb":"decline"}', NULL, 3, 1853, 97),
(1854, 'declining industry', '/dɪˈklaɪnɪŋ ˈɪndəstri/', 'noun', '{"zh-TW":["衰退行業"],"en":["an industry experiencing decreasing demand or output"]}', NULL, 'operate in a declining industry / revitalize a declining industry', '[{"en":"Print media is often cited as a declining industry.","zh-TW":"印刷媒體經常被視為衰退行業的例子。"},{"en":"Companies in declining industries must innovate to survive.","zh-TW":"衰退行業中的公司必須創新才能生存。"}]', NULL, NULL, 5, 1854, NULL),
(1855, 'decommission', '/ˌdiːkəˈmɪʃən/', 'verb', '{"zh-TW":["退役；停用"],"en":["to take a piece of equipment or system out of service permanently"]}', NULL, 'decommission a server / decommission equipment / decommission a plant', '[{"en":"The old data center was decommissioned after the cloud migration.","zh-TW":"雲端遷移後，舊數據中心被退役了。"},{"en":"Decommissioning the factory required careful environmental planning.","zh-TW":"工廠退役需要仔細的環境規劃。"}]', '{"noun":"decommissioning"}', NULL, 4, 1855, NULL),
(1856, 'deconstruct', '/ˌdiːkənˈstrʌkt/', 'verb', '{"zh-TW":["解構；分析"],"en":["to analyze by breaking down into component parts; to apply deconstruction theory"]}', NULL, 'deconstruct an argument / deconstruct assumptions / deconstruct a text', '[{"en":"The scholar deconstructed the text to reveal its hidden assumptions.","zh-TW":"學者對文本進行解構以揭示其隱藏的假設。"},{"en":"Deconstructing a complex problem helps identify its root causes.","zh-TW":"解構複雜問題有助於識別其根本原因。"}]', '{"noun":"deconstruction","adjective":"deconstructive"}', NULL, 4, 1856, NULL),
(1857, 'decrease', '/dɪˈkriːs/', 'verb / noun', '{"zh-TW":["減少；降低"],"en":["to become smaller or fewer in size or amount"]}', NULL, 'significant/steady decrease', '[{"en":"The number of employees decreased significantly.","zh-TW":"員工人數大幅減少。"},{"en":"There has been a decrease in demand.","zh-TW":"需求有所下降。"}]', '{"noun":"decrease","verb":"decrease"}', NULL, 3, 1857, 322),
(1858, 'decree', '/dɪˈkriː/', 'noun', '{"zh-TW":["法令；判決"],"en":["an official order issued by a legal authority"]}', NULL, 'royal decree / issue a decree', '[{"en":"The president issued a decree.","zh-TW":"總統頒布了一項法令。"},{"en":"The court issued a divorce decree.","zh-TW":"法院發出了離婚判決。"}]', '{"verb":"decree"}', NULL, 2, 1858, NULL),
(1859, 'dedicate', '/ˈdedɪkeɪt/', 'verb', '{"zh-TW":["奉獻；致力於"],"en":["to devote time or effort to a particular purpose","to devote time or effort to something"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"dic","meaning":"declare (宣告)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"完全宣告投入，即「奉獻」。"}', 'dedicate oneself to; dedicate time to / dedicated employee', '[{"en":"She dedicated her life to medical research.","zh-TW":"她把一生奉獻給了醫學研究。"},{"en":"He is dedicated to improving customer service.","zh-TW":"他致力於改善客戶服務。"},{"en":"She dedicated her life to helping others.","zh-TW":"她一生奉獻於幫助他人。"},{"en":"He is a dedicated teacher.","zh-TW":"他是一位盡責的老師。"}]', '{"noun":"dedication","verb":"dedicate","adjective":"dedicated"}', NULL, 3, 1859, NULL),
(1860, 'dedicated', '/ˈdɛdɪkeɪtɪd/', 'adjective', '{"zh-TW":["專注的；專用的；投入的"],"en":["devoted to a task or purpose"]}', NULL, 'dedicated employee / dedicated team', '[{"en":"She is a highly dedicated and reliable team member.","zh-TW":"她是一位高度投入且可靠的團隊成員。"},{"en":"We have a dedicated support team available 24/7.","zh-TW":"我們有一個全天24小時的專用支援團隊。"}]', '{"verb":"dedicate","noun":"dedication"}', NULL, 3, 1860, 323),
(1861, 'deduce', '/dɪˈdjuːs/', 'verb', '{"zh-TW":["推斷；演繹"],"en":["to arrive at a conclusion by reasoning from known facts"]}', NULL, 'deduce from evidence / deduce a conclusion / logically deduce', '[{"en":"From the data, we can deduce that demand is increasing.","zh-TW":"從數據中，我們可以推斷出需求正在增加。"},{"en":"She deduced the cause of the error from the system logs.","zh-TW":"她從系統日誌中推斷出錯誤的原因。"}]', '{"noun":"deduction","adjective":"deducible"}', NULL, 2, 1861, NULL),
(1862, 'deduct', '/dɪˈdʌkt/', 'verb', '{"zh-TW":["扣除；減去"],"en":["to subtract an amount from a total"]}', NULL, 'deduct from salary/taxes', '[{"en":"Tax is deducted from your salary automatically.","zh-TW":"稅款會自動從薪水中扣除。"},{"en":"You can deduct business expenses from income.","zh-TW":"你可以從收入中扣除商業費用。"}]', '{"noun":"deduction","verb":"deduct","adjective":"deductible"}', NULL, 2, 1862, 324),
(1863, 'deductible', '/dɪˈdʌktɪbəl/', 'noun', '{"zh-TW":["免賠額；自負額"],"en":["the amount paid before insurance begins to cover costs"]}', NULL, 'annual deductible / high deductible plan', '[{"en":"You must meet your deductible before claims are paid.","zh-TW":"在理賠支付前，您必須達到免賠額。"},{"en":"Choosing a higher deductible lowers your monthly premium.","zh-TW":"選擇較高的免賠額可降低每月保費。"}]', '{"verb":"deduct","adjective":"deductible"}', NULL, 4, 1863, 853),
(1864, 'deduction', '/dɪˈdʌkʃən/', 'noun', '{"zh-TW":["演繹；扣除"],"en":["the process of reaching a conclusion by reasoning; an amount subtracted"]}', NULL, 'logical deduction / tax deduction / pre-tax deduction', '[{"en":"Employees may claim a deduction for home office expenses on their tax returns.","zh-TW":"員工可在納稅申報單上申請家庭辦公室費用的扣除。"},{"en":"The detective''s deduction identified the suspect from limited clues.","zh-TW":"偵探從有限的線索中進行演繹，確定了嫌疑人。"}]', '{"verb":"deduce","adjective":"deductive"}', NULL, 3, 1864, NULL),
(1865, 'deductive', '/dɪˈdʌktɪv/', 'adjective', '{"zh-TW":["演繹的；推斷的"],"en":["relating to reasoning from general principles to specific conclusions"]}', NULL, 'deductive reasoning / deductive logic / deductive method', '[{"en":"The detective used deductive reasoning to solve the case.","zh-TW":"偵探使用演繹推理來解決案件。"},{"en":"Deductive logic is foundational to scientific research.","zh-TW":"演繹邏輯是科學研究的基礎。"}]', '{"noun":"deduction","verb":"deduce","adverb":"deductively"}', NULL, 3, 1865, NULL),
(1866, 'deed', '/diːd/', 'noun', '{"zh-TW":["契約；法律文件"],"en":["a signed legal document transferring property or rights"]}', NULL, 'sign a deed / property deed', '[{"en":"The deed to the property was transferred after the sale.","zh-TW":"財產的契約在出售後轉讓了。"},{"en":"A deed of transfer must be witnessed and notarized.","zh-TW":"轉讓契約必須有見證人並公證。"}]', NULL, NULL, 1, 1866, NULL),
(1867, 'deed of assignment', '/diːd əv əˈsaɪnmənt/', 'noun', '{"zh-TW":["轉讓契約"],"en":["a legal document transferring ownership of an asset or right to another party"]}', NULL, 'execute a deed of assignment / deed of assignment requirements', '[{"en":"A deed of assignment was used to transfer the intellectual property rights.","zh-TW":"轉讓契約用於轉移知識產權。"},{"en":"The deed of assignment must be notarized to be legally enforceable.","zh-TW":"轉讓契約必須經公證才能具有法律效力。"}]', NULL, NULL, 5, 1867, NULL),
(1868, 'deep', '/diːp/', 'adjective', '{"zh-TW":["深的；深刻的","深的"],"en":["extending far down","very strong or intense","going far down from the surface"]}', NULL, 'deep analysis / in deep trouble; deep water / deep breath', '[{"en":"We need a deeper analysis of the data.","zh-TW":"我們需要更深入的數據分析。"},{"en":"The company is in deep financial trouble.","zh-TW":"公司陷入了嚴重的財務困境。"},{"en":"The river is very deep here.","zh-TW":"河在這裡非常深。"},{"en":"Take a deep breath and relax.","zh-TW":"深呼吸然後放鬆。"}]', '{"adjective":"deep","adverb":"deeply","verb":"deepen","noun":"depth"}', NULL, 1, 1868, NULL),
(1869, 'deep learning', '/diːp ˈlɜːrnɪŋ/', 'noun', '{"zh-TW":["深度學習"],"en":["a subset of machine learning using multi-layered neural networks"]}', NULL, 'train deep learning model / deep learning algorithm / deep learning application', '[{"en":"Deep learning has revolutionized image and speech recognition.","zh-TW":"深度學習徹底改變了圖像和語音識別技術。"},{"en":"Deep learning models require large amounts of labeled training data.","zh-TW":"深度學習模型需要大量有標籤的訓練數據。"}]', NULL, NULL, 5, 1869, NULL),
(1870, 'default', '/dɪˈfɔːlt/', 'noun / verb', '{"zh-TW":["違約；預設"],"en":["failure to fulfill an obligation; a preset value"]}', NULL, 'by default', '[{"en":"The company defaulted on its loan.","zh-TW":"該公司貸款違約了。"},{"en":"The settings are restored to default.","zh-TW":"設定已恢復為預設值。"}]', '{"noun":"default","verb":"default"}', NULL, 3, 1870, 325),
(1871, 'default judgment', '/dɪˈfɔːlt ˈdʒʌdʒmənt/', 'noun', '{"zh-TW":["缺席判決"],"en":["a court ruling in favor of the plaintiff when the defendant fails to respond"]}', NULL, 'obtain a default judgment / default judgment motion / set aside a default judgment', '[{"en":"The court entered a default judgment after the defendant failed to appear.","zh-TW":"被告未出庭後，法院作出了缺席判決。"},{"en":"A default judgment can be set aside if the defendant provides good reasons.","zh-TW":"如果被告提供充分理由，缺席判決可以被撤銷。"}]', NULL, NULL, 5, 1871, NULL),
(1872, 'default risk', '/dɪˈfɔːlt rɪsk/', 'noun', '{"zh-TW":["違約風險"],"en":["the risk that a borrower will fail to repay a loan"]}', NULL, 'assess default risk / high default risk / manage default risk', '[{"en":"Higher interest rates compensate lenders for taking on default risk.","zh-TW":"較高的利率補償了貸款方承擔的違約風險。"},{"en":"Credit ratings are used to assess the default risk of bond issuers.","zh-TW":"信用評等用於評估債券發行者的違約風險。"}]', NULL, NULL, 4, 1872, NULL),
(1873, 'defeat', '/dɪˈfiːt/', 'verb / noun', '{"zh-TW":["擊敗；失敗","擊敗；戰勝"],"en":["to win a victory over someone","to win against someone in a fight or game"]}', NULL, 'suffer/admit defeat; suffer a defeat / admit defeat', '[{"en":"They defeated the rival team 3-1.","zh-TW":"他們以3比1擊敗了對手。"},{"en":"He refused to admit defeat.","zh-TW":"他拒絕承認失敗。"},{"en":"They defeated the champions 2-1.","zh-TW":"他們以2比1擊敗了冠軍隊。"}]', '{"noun":"defeat","verb":"defeat"}', NULL, 2, 1873, NULL),
(1874, 'defend', '/dɪˈfend/', 'verb', '{"zh-TW":["防禦；辯護"],"en":["to protect from harm or danger"]}', NULL, 'defend against', '[{"en":"The lawyer defended her client in court.","zh-TW":"律師在法庭上為她的客戶辯護。"},{"en":"We must defend our market position.","zh-TW":"我們必須捍衛我們的市場地位。"}]', '{"noun":"defense/defendant","verb":"defend","adjective":"defensive"}', NULL, 2, 1874, NULL),
(1875, 'defendant', '/dɪˈfɛndənt/', 'noun', '{"zh-TW":["被告"],"en":["a person accused in a court of law"]}', NULL, 'the defendant pleaded / defendant''s rights', '[{"en":"The defendant pleaded not guilty.","zh-TW":"被告答辯無罪。"},{"en":"The defendant has the right to an attorney.","zh-TW":"被告有權請律師。"}]', '{"verb":"defend","noun2":"defense"}', NULL, 3, 1875, NULL),
(1876, 'defensive strategy', '/''dɪˌfensɪv ˈstrætɪdʒi/', 'noun', '{"zh-TW":["防禦策略；防守戰術"],"en":["a plan or approach focused on preventing the opponent from scoring or gaining advantage"]}', NULL, 'implement a defensive strategy / defensive strategy analysis / adapt defensive strategy', '[{"en":"The team adopted a cautious defensive strategy in the second half of the match.","zh-TW":"球隊在比賽下半場採取了謹慎的防守策略。"},{"en":"A solid defensive strategy requires coordination and communication among all players.","zh-TW":"紮實的防禦策略需要所有球員之間的協調和溝通。"}]', NULL, NULL, 5, 1876, NULL),
(1877, 'defer', '/dɪˈfɜːr/', 'verb', '{"zh-TW":["推遲；順從"],"en":["to postpone; to yield to another''s opinion"]}', NULL, 'defer payment/judgment', '[{"en":"Payment has been deferred until next month.","zh-TW":"付款已延遲到下個月。"},{"en":"I defer to your expertise on this matter.","zh-TW":"在這件事上我尊重你的專業意見。"}]', '{"noun":"deferral","verb":"defer"}', NULL, 2, 1877, 326),
(1878, 'deference', '/''defərəns/', 'noun', '{"zh-TW":["尊重；服從；遵從"],"en":["polite submission and respect to the wishes, decision, or opinion of another"]}', NULL, 'show deference / out of deference / deference to authority', '[{"en":"He showed deference to the senior partner''s judgment on the complex legal matter.","zh-TW":"他對高級合夥人在複雜法律事務上的判斷表示尊重。"},{"en":"Out of deference to the client''s wishes, the team revised the entire proposal.","zh-TW":"出於對客戶意願的遵從，團隊修改了整個提案。"}]', '{"adjective":"deferential","verb":"defer"}', NULL, 3, 1878, NULL),
(1879, 'deferred compensation', '/dɪˈfɜːrd ˌkɒmpənˈseɪʃən/', 'noun', '{"zh-TW":["遞延薪酬"],"en":["a portion of an employee''s pay set aside to be received at a future date"]}', NULL, 'deferred compensation plan / deferred compensation agreement / receive deferred compensation', '[{"en":"Deferred compensation is often used to retain senior executives.","zh-TW":"遞延薪酬通常用於留住高級管理人員。"},{"en":"Tax laws govern when deferred compensation must be included in income.","zh-TW":"稅法規定遞延薪酬何時必須計入收入。"}]', NULL, NULL, 5, 1879, NULL),
(1880, 'deferred payment', '/dɪˈfɜːrd ˈpeɪmənt/', 'noun', '{"zh-TW":["延期付款"],"en":["a payment arrangement where the full amount is paid at a later date"]}', NULL, 'arrange a deferred payment / deferred payment plan', '[{"en":"The company offered customers a deferred payment plan on large orders.","zh-TW":"公司向客戶提供了大額訂單的延期付款計劃。"},{"en":"Deferred payment helps clients manage cash flow on major purchases.","zh-TW":"延期付款幫助客戶管理重大採購的現金流。"}]', NULL, NULL, 5, 1880, NULL),
(1881, 'deferred revenue', '/dɪˈfɜːrd ˈrevɪnjuː/', 'noun', '{"zh-TW":["遞延收入；預收款"],"en":["payment received before goods or services are delivered"]}', NULL, 'recognize deferred revenue / deferred revenue balance / track deferred revenue', '[{"en":"Subscription fees received upfront are recorded as deferred revenue.","zh-TW":"預先收取的訂閱費記錄為遞延收入。"},{"en":"As services are delivered, deferred revenue is recognized as income.","zh-TW":"隨著服務的交付，遞延收入被確認為收入。"}]', NULL, NULL, 5, 1881, NULL),
(1882, 'deferred tax', '/dɪˈfɜːrd tæks/', 'noun', '{"zh-TW":["遞延所得稅"],"en":["tax liability or asset arising from temporary differences in accounting and tax rules"]}', NULL, 'deferred tax liability / deferred tax asset / recognize deferred tax', '[{"en":"A deferred tax liability arose from accelerated depreciation.","zh-TW":"加速折舊導致了遞延所得稅負債。"},{"en":"Deferred tax assets were recognized based on future income projections.","zh-TW":"根據未來收入預測確認了遞延所得稅資產。"}]', NULL, NULL, 4, 1882, NULL),
(1883, 'defibrillator', '/dɪˈfɪbrɪleɪtər/', 'noun', '{"zh-TW":["去顫器"],"en":["a device that delivers a controlled electric shock to restore heart rhythm"]}', NULL, 'use a defibrillator / automated defibrillator / portable defibrillator', '[{"en":"The airport is equipped with automated defibrillators for cardiac emergencies.","zh-TW":"機場配備了用於心臟緊急情況的自動去顫器。"},{"en":"CPR combined with defibrillation greatly improves cardiac arrest survival.","zh-TW":"心肺復甦術結合去顫大大提高了心臟驟停的生存率。"}]', NULL, NULL, 5, 1883, NULL),
(1884, 'deficiency', '/dɪˈfɪʃənsi/', 'noun', '{"zh-TW":["不足；缺陷"],"en":["a lack or shortage of something required"]}', NULL, 'capital deficiency / skill deficiency / deficiency in controls', '[{"en":"The audit identified a deficiency in the internal approval controls.","zh-TW":"審計發現了內部審批控制方面的缺陷。"},{"en":"A deficiency in working capital was the main cause of the crisis.","zh-TW":"營運資金不足是危機的主要原因。"}]', '{"adjective":"deficient"}', NULL, 4, 1884, 1000),
(1885, 'deficit', '/ˈdefɪsɪt/', 'noun', '{"zh-TW":["赤字；不足"],"en":["the amount by which something falls short"]}', NULL, 'budget/trade deficit', '[{"en":"The government is trying to reduce the budget deficit.","zh-TW":"政府正在試圖減少預算赤字。"},{"en":"The trade deficit widened last year.","zh-TW":"去年貿易逆差擴大了。"}]', '{"noun":"deficit"}', NULL, 3, 1885, 854),
(1886, 'deficit financing', '/ˈdefɪsɪt ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["赤字融資"],"en":["the practice of covering government spending with borrowed money rather than tax revenue"]}', NULL, 'rely on deficit financing / deficit financing model / limit deficit financing', '[{"en":"Governments use deficit financing to fund public works programs during recessions.","zh-TW":"政府在衰退期間使用赤字融資來資助公共工程計畫。"},{"en":"Persistent deficit financing raises long-term concerns about debt sustainability.","zh-TW":"持續的赤字融資引發了對債務可持續性的長期擔憂。"}]', NULL, NULL, 5, 1886, NULL),
(1887, 'define', '/dɪˈfaɪn/', 'verb', '{"zh-TW":["定義；界定"],"en":["to state the exact meaning of something"]}', NULL, 'clearly define', '[{"en":"Please define your objectives clearly.","zh-TW":"請清楚地界定你的目標。"},{"en":"The contract defines the terms of employment.","zh-TW":"合約界定了僱用條件。"}]', '{"noun":"definition","verb":"define","adjective":"definite"}', NULL, 2, 1887, 327),
(1888, 'deflation', '/dɪˈfleɪʃən/', 'noun', '{"zh-TW":["通貨緊縮"],"en":["a decline in the general price level of goods and services"]}', NULL, 'risk of deflation / deflationary pressure / combat deflation', '[{"en":"Deflation can discourage consumer spending.","zh-TW":"通貨緊縮可能抑制消費者支出。"},{"en":"Japan struggled with deflation for over a decade.","zh-TW":"日本與通貨緊縮鬥爭了超過十年。"}]', '{"adjective":"deflationary","verb":"deflate"}', NULL, 3, 1888, NULL),
(1889, 'deforestation', '/ˌdiːˌfɒrɪˈsteɪʃən/', 'noun', '{"zh-TW":["森林砍伐；毀林"],"en":["the clearing of forests by humans"]}', NULL, 'stop deforestation / deforestation rate', '[{"en":"Deforestation destroys habitats and contributes to climate change.","zh-TW":"森林砍伐破壞棲地並加劇氣候變遷。"},{"en":"Brazil is working to reduce deforestation in the Amazon.","zh-TW":"巴西正在努力減少亞馬遜的森林砍伐。"}]', '{"verb":"deforest","adjective":"deforested"}', NULL, 5, 1889, NULL),
(1890, 'degenerative', '/dɪˈdʒenərətɪv/', 'adjective', '{"zh-TW":["退化性的；變質的"],"en":["characterized by progressive deterioration of function or structure"]}', NULL, 'degenerative disease / degenerative condition / degenerative joint disease', '[{"en":"Arthritis is a degenerative disease that worsens without treatment.","zh-TW":"關節炎是一種不治療就會惡化的退化性疾病。"},{"en":"Research into degenerative neurological diseases is a major scientific priority.","zh-TW":"退化性神經系統疾病的研究是主要的科學優先事項。"}]', '{"verb":"degenerate","noun":"degeneration"}', NULL, 4, 1890, NULL),
(1891, 'degree', '/dɪˈɡriː/', 'noun', '{"zh-TW":["學位；程度；度","學位；程度"],"en":["an academic qualification","an amount or level","a qualification from a university"]}', NULL, 'to a degree / master''s degree; bachelor''s degree / to some degree', '[{"en":"She has a master''s degree in finance.","zh-TW":"她有金融碩士學位。"},{"en":"To what degree is this accurate?","zh-TW":"這在多大程度上是準確的？"},{"en":"She has a degree in engineering.","zh-TW":"她有工程學位。"},{"en":"To some degree, I agree with you.","zh-TW":"在某種程度上，我同意你。"}]', '{"noun":"degree"}', NULL, 2, 1891, NULL),
(1892, 'dehydrate', '/''diːhaɪdreɪt/', 'verb', '{"zh-TW":["脫水；使乾燥"],"en":["to remove water from food, or for the body to lose too much water"]}', NULL, 'dehydrate food / dehydrate in the oven / become dehydrated', '[{"en":"She used a dehydrator to dehydrate sliced mangoes into chips.","zh-TW":"她使用脫水機將切片芒果脫水製成芒果乾。"},{"en":"Athletes must stay hydrated in hot weather to avoid becoming dehydrated.","zh-TW":"運動員必須在炎熱天氣保持水分，以避免脫水。"}]', '{"noun":"dehydration","adjective":"dehydrated"}', NULL, 3, 1892, NULL),
(1893, 'dehydrated', '/''diːhaɪˌdreɪtɪd/', 'adjective', '{"zh-TW":["脫水的；乾燥的"],"en":["lacking sufficient water; having had water removed in the process of preservation"]}', NULL, 'feeling dehydrated / dehydrated food / dehydrated skin', '[{"en":"Dehydrated fruits like raisins and dried cranberries make nutritious snacks.","zh-TW":"脫水水果如葡萄乾和蔓越莓乾是有營養的零食。"},{"en":"After the long run, she felt dehydrated and drank several glasses of water.","zh-TW":"長跑後，她感到脫水，喝了幾杯水。"}]', '{"verb":"dehydrate","noun":"dehydration"}', NULL, 4, 1893, NULL),
(1894, 'DEI', '/ˌdiː iː ˈaɪ/', 'noun', '{"zh-TW":["多元平等共融"],"en":["diversity, equity, and inclusion; efforts to promote fair workplaces"]}', NULL, 'DEI initiatives / DEI policy / DEI training / DEI strategy', '[{"en":"The company appointed a Chief Diversity Officer to lead DEI efforts.","zh-TW":"公司任命了首席多元長來領導多元平等共融工作。"},{"en":"DEI training is now mandatory for all managers.","zh-TW":"多元平等共融培訓現在對所有管理者是強制性的。"}]', '{"full form":"diversity, equity, and inclusion"}', NULL, 1, 1894, NULL),
(1895, 'deindustrialization', '/ˌdiːɪnˌdʌstriəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["去工業化"],"en":["the reduction of industrial activity in an area or economy"]}', NULL, 'impact of deindustrialization / deindustrialization of cities / cope with deindustrialization', '[{"en":"Deindustrialization left many manufacturing towns with high unemployment.","zh-TW":"去工業化使許多製造業城鎮面臨高失業率。"},{"en":"Deindustrialization is often linked to the decline of working-class communities.","zh-TW":"去工業化通常與工人階級社區的衰落有關。"}]', '{"verb":"deindustrialize","adjective":"deindustrialized"}', NULL, 5, 1895, NULL),
(1896, 'delay', '/dɪˈleɪ/', 'verb / noun', '{"zh-TW":["延遲；耽擱"],"en":["to make something happen later than expected"]}', NULL, 'without delay', '[{"en":"The flight was delayed by two hours.","zh-TW":"航班延誤了兩個小時。"},{"en":"Please respond without delay.","zh-TW":"請立即回覆。"}]', '{"noun":"delay","verb":"delay","adjective":"delayed"}', NULL, 2, 1896, 328),
(1897, 'delegate', '/ˈdelɪɡeɪt/', 'verb / noun', '{"zh-TW":["委派；代表"],"en":["to give a task or responsibility to someone else"]}', NULL, 'delegate authority/tasks', '[{"en":"A good manager knows how to delegate tasks.","zh-TW":"好的管理者知道如何委派任務。"},{"en":"Each country sent a delegate to the conference.","zh-TW":"每個國家都派了代表出席會議。"}]', '{"noun":"delegate/delegation","verb":"delegate"}', NULL, 3, 1897, 98),
(1898, 'delegating', '/''delɪˌɡeɪtɪŋ/', 'noun', '{"zh-TW":["授權；委派"],"en":["the act of entrusting tasks or responsibilities to another person"]}', NULL, 'effective delegating / practice delegating / skill of delegating', '[{"en":"Effective delegating allows managers to focus on high-priority strategic tasks.","zh-TW":"有效授權使管理者能夠專注於高優先級的戰略任務。"},{"en":"She found delegating difficult at first but learned that it empowered her team.","zh-TW":"她起初發現授權很困難，但後來意識到它能夠賦予她的團隊權力。"}]', '{"verb":"delegate"}', NULL, 4, 1898, NULL),
(1899, 'delegation', '/ˌdelɪˈɡeɪʃən/', 'noun', '{"zh-TW":["授權；代表團"],"en":["assigning responsibility and authority to someone else; also a group of representatives"]}', NULL, 'effective delegation / delegation of authority / international delegation', '[{"en":"Effective delegation allows managers to focus on strategic work.","zh-TW":"有效的授權讓管理者能夠專注於策略性工作。"},{"en":"A delegation from three countries attended the trade summit.","zh-TW":"來自三個國家的代表團出席了貿易峰會。"}]', '{"verb":"delegate","adjective":"delegated"}', NULL, 4, 1899, 540);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1900, 'deleveraging', '/diːˈlevərɪdʒɪŋ/', 'noun', '{"zh-TW":["去槓桿化"],"en":["the process of reducing borrowing and financial leverage"]}', NULL, 'debt deleveraging / forced deleveraging / corporate deleveraging', '[{"en":"Household deleveraging after the financial crisis reduced consumer spending significantly.","zh-TW":"金融危機後的家庭去槓桿化大幅減少了消費者支出。"},{"en":"Corporate deleveraging improved balance sheet health but slowed investment.","zh-TW":"企業去槓桿化改善了資產負債表健康狀況，但放緩了投資。"}]', '{"verb":"deleverage","adjective":"deleveraged"}', NULL, 4, 1900, NULL),
(1901, 'deli', '/ˈdɛli/', 'noun', '{"zh-TW":["熟食店；美食店"],"en":["a shop selling prepared foods, meats, and cheeses"]}', NULL, 'local deli / deli counter', '[{"en":"We stopped at the deli to pick up sandwiches for lunch.","zh-TW":"我們在熟食店停下來買了午餐三明治。"},{"en":"The deli offers over 50 varieties of cheese.","zh-TW":"這家熟食店提供超過50種起司。"}]', NULL, NULL, 1, 1901, NULL),
(1902, 'deliberate', '/dɪˈlɪbərət/', 'adjective / verb', '{"zh-TW":["故意的；審慎的"],"en":["done intentionally; to think carefully","done consciously and intentionally"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"liber","meaning":"weigh (衡量)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"完全經過衡量的，即「審慎的」或「故意的」。"}', 'deliberate action/decision; deliberate action / deliberate decision', '[{"en":"It was a deliberate attempt to mislead investors.","zh-TW":"這是故意誤導投資者的行為。"},{"en":"The jury deliberated for three days.","zh-TW":"陪審團審議了三天。"},{"en":"It was a deliberate attempt to mislead the public.","zh-TW":"這是故意誤導公眾的企圖。"},{"en":"She made a deliberate choice to change careers.","zh-TW":"她審慎地決定轉換職業。"}]', '{"noun":"deliberation","verb":"deliberate","adjective":"deliberate","adverb":"deliberately"}', NULL, 4, 1902, 965),
(1903, 'deliberative democracy', '/dɪˈlɪbərətɪv dɪˈmɒkrəsi/', 'noun', '{"zh-TW":["審議民主"],"en":["a form of democracy emphasizing rational discussion and informed decision-making"]}', NULL, 'practice deliberative democracy / deliberative democracy model / benefit of deliberative democracy', '[{"en":"Deliberative democracy emphasizes reason and evidence over majority preference.","zh-TW":"審議民主強調理性和證據，而非多數人的偏好。"},{"en":"Citizens'' assemblies are a tool of deliberative democracy in practice.","zh-TW":"公民議會是審議民主在實踐中的工具。"}]', NULL, NULL, 5, 1903, NULL),
(1904, 'delinquent account', '/dɪˈlɪŋkwənt əˈkaʊnt/', 'noun', '{"zh-TW":["逾期帳戶；拖欠帳戶"],"en":["an account where the customer has failed to make scheduled payments"]}', NULL, 'identify delinquent accounts / manage delinquent accounts', '[{"en":"The collections team contacts all delinquent accounts within 30 days.","zh-TW":"追收團隊在30天內聯繫所有逾期帳戶。"},{"en":"Delinquent accounts are transferred to a specialist recovery team.","zh-TW":"逾期帳戶被移交給專業追收團隊。"}]', '{"adjective":"delinquent","noun":"delinquency"}', NULL, 5, 1904, NULL),
(1905, 'delisting', '/diːˈlɪstɪŋ/', 'noun', '{"zh-TW":["摘牌；退市"],"en":["the removal of a company from a stock exchange listing"]}', NULL, 'delist from the exchange / face delisting', '[{"en":"The company faced delisting after failing to meet reporting requirements.","zh-TW":"公司因未能滿足報告要求而面臨退市。"},{"en":"Delisting removed the company from the public markets.","zh-TW":"退市使公司退出了公開市場。"}]', '{"verb":"delist","adjective":"delisted"}', NULL, 3, 1905, NULL),
(1906, 'deliver', '/dɪˈlɪvər/', 'verb', '{"zh-TW":["遞送；發表"],"en":["to bring goods to a destination; to give a speech","to take something to a person or place"]}', NULL, 'deliver goods/a speech; deliver a speech / deliver goods', '[{"en":"The package will be delivered tomorrow.","zh-TW":"包裹明天會送達。"},{"en":"She delivered an inspiring presentation.","zh-TW":"她發表了一場鼓舞人心的演講。"},{"en":"The package was delivered this morning.","zh-TW":"包裹今天早上送到了。"},{"en":"She delivered an inspiring speech.","zh-TW":"她發表了一場鼓舞人心的演講。"}]', '{"noun":"delivery","verb":"deliver"}', NULL, 3, 1906, 99),
(1907, 'deliver on time', '/dɪˈlɪvər ɒn taɪm/', 'verb', '{"zh-TW":["按時交付；準時交貨"],"en":["to complete and hand over something by the agreed deadline"]}', NULL, 'deliver projects on time / consistently deliver on time', '[{"en":"The contractor delivered the project on time and within budget.","zh-TW":"承包商按時且在預算內交付了項目。"},{"en":"Failing to deliver on time resulted in penalty charges.","zh-TW":"未能按時交付導致了違約罰款。"}]', NULL, NULL, 5, 1907, NULL),
(1908, 'deliverable', '/dɪˈlɪvərəbl/', 'noun', '{"zh-TW":["可交付成果"],"en":["an output or result that must be produced as part of a project"]}', NULL, 'project deliverable / submit deliverables / key deliverable', '[{"en":"All deliverables must be submitted by the deadline.","zh-TW":"所有可交付成果必須在截止日期前提交。"},{"en":"The contract specifies the deliverables and acceptance criteria.","zh-TW":"合同規定了可交付成果和驗收標準。"}]', '{"plural":"deliverables"}', NULL, 4, 1908, 773),
(1909, 'deliverable outcome', '/dɪˈlɪvərəbəl ˈaʊtkʌm/', 'noun', '{"zh-TW":["交付成果"],"en":["a specific measurable result from a project or engagement"]}', NULL, 'define deliverable outcomes / track deliverable outcomes', '[{"en":"Each phase of the project has defined deliverable outcomes.","zh-TW":"項目的每個階段都有明確的交付成果。"},{"en":"Deliverable outcomes were reviewed by the client at each milestone.","zh-TW":"客戶在每個里程碑處審查了交付成果。"}]', NULL, NULL, 5, 1909, NULL),
(1910, 'deliverable schedule', '/dɪˈlɪvərəbəl ˈʃedjuːl/', 'noun', '{"zh-TW":["可交付成果時間表"],"en":["a planned timeline for completing and submitting project outputs"]}', NULL, 'follow the deliverable schedule / set up a deliverable schedule', '[{"en":"The deliverable schedule mapped out key milestones over 12 months.","zh-TW":"可交付成果時間表規劃了12個月內的關鍵里程碑。"},{"en":"Delays in the deliverable schedule triggered a project review.","zh-TW":"可交付成果時間表的延誤引發了項目審查。"}]', NULL, NULL, 5, 1910, NULL),
(1911, 'delivery', '/dɪˈlɪvəri/', 'noun', '{"zh-TW":["遞送；交付"],"en":["the act of bringing goods to a person"]}', '{"prefix":{"text":"de-","meaning":"away (離開)"},"root":{"text":"liver","meaning":"free (釋放)"},"logic":"釋放出去的行為，即「遞送」。"}', 'free delivery / express delivery', '[{"en":"Delivery takes three to five business days.","zh-TW":"遞送需要三到五個工作天。"},{"en":"We offer free delivery on orders over $50.","zh-TW":"滿50美元免運費。"}]', '{"verb":"deliver"}', NULL, 3, 1911, NULL),
(1912, 'delivery confirmation', '/''dɪˌlɪvəri ˌkɒnfɜːˈmeɪʃən/', 'noun', '{"zh-TW":["送達確認；交付確認"],"en":["a notification confirming that a shipment or package has been delivered"]}', NULL, 'receive delivery confirmation / delivery confirmation email / provide delivery confirmation', '[{"en":"She received a delivery confirmation email as soon as the package was delivered.","zh-TW":"包裹送達後，她立即收到了送達確認電子郵件。"},{"en":"Delivery confirmation is required before the seller can release the final payment.","zh-TW":"在賣方可以釋放最終付款之前，需要送達確認。"}]', NULL, NULL, 5, 1912, NULL),
(1913, 'delivery duty paid', '/dɪˈlɪvəri ˈdjuːti peɪd/', 'phrase', '{"zh-TW":["完稅後交貨"],"en":["an Incoterm where the seller bears all costs and risks to deliver goods at destination"]}', NULL, 'sell on delivery duty paid terms / delivery duty paid pricing', '[{"en":"Under delivery duty paid, the seller handles customs clearance at destination.","zh-TW":"在完稅後交貨條件下，賣方負責目的地的海關清關。"},{"en":"Buyers often prefer delivery duty paid for the simplicity it offers.","zh-TW":"買方通常更喜歡完稅後交貨，因為它提供的便利性。"}]', '{"abbreviation":"DDP"}', NULL, 5, 1913, NULL),
(1914, 'delivery note', '/dɪˈlɪvəri noʊt/', 'noun', '{"zh-TW":["送貨單；交貨單"],"en":["a document accompanying a shipment listing the goods delivered"]}', NULL, 'sign the delivery note / attach the delivery note', '[{"en":"The warehouse manager signed the delivery note on receipt.","zh-TW":"倉庫管理員在收貨時簽署了送貨單。"},{"en":"The delivery note listed 500 units of the product.","zh-TW":"送貨單上列明了500件產品。"}]', NULL, NULL, 5, 1914, NULL),
(1915, 'delivery order', '/dɪˈlɪvəri ˈɔːrdər/', 'noun', '{"zh-TW":["交貨單；交付指令"],"en":["an instruction to release goods from a warehouse or carrier"]}', NULL, 'issue a delivery order / present the delivery order', '[{"en":"The delivery order must be presented to collect the goods.","zh-TW":"必須出示交貨單才能提取貨物。"},{"en":"The warehouse released the goods upon receipt of the delivery order.","zh-TW":"倉庫在收到交貨單後放行了貨物。"}]', NULL, NULL, 5, 1915, NULL),
(1916, 'delivery route', '/''dɪˌlɪvəri ruːt/', 'noun', '{"zh-TW":["配送路線；送貨路線"],"en":["the path taken by a delivery driver to deliver goods to multiple locations"]}', NULL, 'optimize delivery route / plan delivery route / delivery route software', '[{"en":"Optimizing delivery routes reduced fuel costs by twenty-five percent.","zh-TW":"優化配送路線使燃油成本降低了百分之二十五。"},{"en":"The delivery driver used an app to navigate the most efficient delivery route.","zh-TW":"送貨司機使用應用程式導航最高效的配送路線。"}]', NULL, NULL, 5, 1916, NULL),
(1917, 'delivery schedule', '/dɪˈlɪvəri ˈʃedjuːl/', 'noun', '{"zh-TW":["交貨時間表"],"en":["a plan specifying the dates and quantities for delivering goods or services"]}', NULL, 'agree on a delivery schedule / delivery schedule delay', '[{"en":"The supplier committed to a weekly delivery schedule for the raw materials.","zh-TW":"供應商承諾按週的交貨時間表交付原材料。"},{"en":"The delivery schedule was revised after a supplier announced capacity constraints.","zh-TW":"在供應商宣布產能限制後，交貨時間表進行了修訂。"}]', NULL, NULL, 5, 1917, NULL),
(1918, 'deluxe room', '/dɪˈlʌks ruːm/', 'noun', '{"zh-TW":["豪華客房"],"en":["a higher-grade hotel room with premium features"]}', NULL, 'book a deluxe room / deluxe room upgrade', '[{"en":"We booked a deluxe room with a city view.","zh-TW":"我們預訂了可欣賞城市景觀的豪華客房。"},{"en":"The deluxe room includes a king-size bed and jacuzzi.","zh-TW":"豪華客房包含特大床和按摩浴缸。"}]', NULL, NULL, 4, 1918, NULL),
(1919, 'demand', '/dɪˈmænd/', 'noun / verb', '{"zh-TW":["需求；要求"],"en":["a strong request; the desire for goods or services","a strong request; the desire for goods"]}', NULL, 'meet/supply demand; in demand / supply and demand', '[{"en":"Consumer demand for organic food is growing.","zh-TW":"消費者對有機食品的需求正在增長。"},{"en":"Workers demanded higher wages.","zh-TW":"工人要求更高的工資。"},{"en":"There''s a high demand for nurses.","zh-TW":"對護士的需求很高。"},{"en":"Supply and demand affect prices.","zh-TW":"供需影響價格。"}]', '{"noun":"demand","verb":"demand","adjective":"demanding"}', NULL, 2, 1919, NULL),
(1920, 'demand elasticity', '/dɪˈmɑːnd ˌɪlæˈstɪsɪti/', 'noun', '{"zh-TW":["需求彈性"],"en":["the responsiveness of demand to changes in price or income"]}', NULL, 'measure demand elasticity / inelastic demand', '[{"en":"Luxury goods tend to have higher demand elasticity than staples.","zh-TW":"奢侈品的需求彈性往往比主食類產品高。"},{"en":"Understanding demand elasticity is essential for effective pricing.","zh-TW":"了解需求彈性對於有效定價至關重要。"}]', NULL, NULL, 5, 1920, NULL),
(1921, 'demand forecast', '/dɪˈmɑːnd ˈfɔːrkæst/', 'noun', '{"zh-TW":["需求預測"],"en":["an estimate of future customer demand for a product or service"]}', NULL, 'prepare a demand forecast / accurate demand forecast', '[{"en":"Accurate demand forecasting reduces overstock and out-of-stock situations.","zh-TW":"準確的需求預測減少了庫存過多和缺貨情況。"},{"en":"The demand forecast was adjusted after the competitor closed.","zh-TW":"競爭對手關閉後調整了需求預測。"}]', NULL, NULL, 5, 1921, NULL),
(1922, 'demand forecasting', '/dɪˈmɑːnd ˈfɔːrkæstɪŋ/', 'noun', '{"zh-TW":["需求預測"],"en":["estimating future customer demand for goods or services"]}', NULL, 'improve demand forecasting / demand forecasting model', '[{"en":"Demand forecasting helps align production with expected sales.","zh-TW":"需求預測有助於使生產與預期銷售保持一致。"},{"en":"The company adopted machine learning for demand forecasting.","zh-TW":"公司採用了機器學習進行需求預測。"}]', NULL, NULL, 5, 1922, NULL),
(1923, 'demerger', '/diːˈmɜːrdʒər/', 'noun', '{"zh-TW":["分拆；分離"],"en":["the separation of a company into two or more independent entities"]}', NULL, 'undergo a demerger / complete a demerger', '[{"en":"The conglomerate completed a demerger to unlock separate business values.","zh-TW":"企業集團完成了分拆以釋放各業務的獨立價值。"},{"en":"The demerger allowed each entity to focus on its core competency.","zh-TW":"分拆允許每個實體專注於其核心競爭力。"}]', '{"verb":"demerge"}', NULL, 3, 1923, NULL),
(1924, 'democracy', '/dɪˈmɒkrəsi/', 'noun', '{"zh-TW":["民主；民主制度","民主"],"en":["government by the people","a system of government by the people"]}', '{"root":{"text":"demo","meaning":"people (人民)"},"suffix":{"text":"cracy","meaning":"rule (統治)"},"logic":"人民統治，即「民主」。"}', 'democratic society / promote democracy; promote democracy / democratic process', '[{"en":"Democracy gives everyone a voice.","zh-TW":"民主賦予每個人發言權。"},{"en":"They fought to protect democracy.","zh-TW":"他們為保護民主而戰。"},{"en":"Democracy gives citizens the right to vote.","zh-TW":"民主賦予公民投票權。"},{"en":"The country transitioned to democracy peacefully.","zh-TW":"該國和平過渡到民主體制。"}]', '{"adjective":"democratic","noun2":"democrat"}', NULL, 3, 1924, NULL),
(1925, 'demographic', '/ˌdeməˈɡræfɪk/', 'adjective', '{"zh-TW":["人口統計的"],"en":["relating to the statistical characteristics of a population"]}', NULL, 'demographic data / demographic targeting / demographic profile / demographic trends', '[{"en":"The demographic data showed the target audience was primarily aged 25-34.","zh-TW":"人口統計數據顯示目標受眾主要是25至34歲。"},{"en":"Shifting demographics are forcing brands to adapt their messaging.","zh-TW":"人口結構的變化迫使品牌調整其訊息傳遞方式。"}]', '{"noun":"demographics"}', NULL, 4, 1925, NULL),
(1926, 'demographic dividend', '/ˌdeməˈɡræfɪk ˈdɪvɪdend/', 'noun', '{"zh-TW":["人口紅利"],"en":["the economic growth resulting from a shift in a country''s age structure"]}', NULL, 'harvest the demographic dividend / demographic dividend effect / lose the demographic dividend', '[{"en":"Countries with young populations can benefit from a demographic dividend.","zh-TW":"擁有年輕人口的國家可以從人口紅利中受益。"},{"en":"Education investment is key to converting population growth into a demographic dividend.","zh-TW":"教育投資是將人口增長轉化為人口紅利的關鍵。"}]', NULL, NULL, 5, 1926, NULL),
(1927, 'demographic shift', '/ˌdeməˈɡræfɪk ʃɪft/', 'noun', '{"zh-TW":["人口結構轉變"],"en":["a significant change in the composition or characteristics of a population"]}', NULL, 'major demographic shift / demographic shift in aging / anticipate demographic shift', '[{"en":"An aging population represents a profound demographic shift for pension systems.","zh-TW":"人口老齡化代表著養老金制度面臨的深刻人口結構轉變。"},{"en":"Demographic shifts are reshaping electoral politics in many countries.","zh-TW":"人口結構轉變正在重塑許多國家的選舉政治。"}]', '{"adjective":"demographic"}', NULL, 5, 1927, NULL),
(1928, 'demographic trend', '/''demə''ɡræfɪk trend/', 'noun', '{"zh-TW":["人口趨勢"],"en":["a general pattern or direction in how population characteristics are changing over time"]}', NULL, 'analyze demographic trends / demographic trend shift / key demographic trend', '[{"en":"Demographic trends show an increasing number of people living alone in urban areas.","zh-TW":"人口趨勢顯示，城市地區越來越多的人獨居。"},{"en":"Companies use demographic trend data to plan product development for future markets.","zh-TW":"公司使用人口趨勢數據為未來市場規劃產品開發。"}]', '{"adjective":"demographic","noun2":"trend"}', NULL, 5, 1928, NULL),
(1929, 'demography', '/''dɪˌmɒɡrəfi/', 'noun', '{"zh-TW":["人口學；人口統計"],"en":["the study of statistics such as births, deaths, income, or the incidence of disease to illustrate human populations"]}', NULL, 'study demography / demography research / demographic data', '[{"en":"The school uses demography data to plan for future enrollment needs.","zh-TW":"學校使用人口統計數據來規劃未來的入學需求。"},{"en":"Understanding demography is essential for developing effective public health policies.","zh-TW":"了解人口學對於制定有效的公共衛生政策至關重要。"}]', '{"adjective":"demographic","adverb":"demographically","noun2":"demographer"}', NULL, 4, 1929, NULL),
(1930, 'demonstrate', '/ˈdemənstreɪt/', 'verb', '{"zh-TW":["展示；證明"],"en":["to show clearly; to prove","to show clearly","to prove by giving evidence"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"monstr","meaning":"show (展示)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"完全展示出來，即「證明」。"}', 'demonstrate ability/skills; demonstrate how / clearly demonstrate', '[{"en":"The data demonstrates a clear trend.","zh-TW":"數據顯示了一個明確的趨勢。"},{"en":"She demonstrated how to use the software.","zh-TW":"她展示了如何使用該軟體。"},{"en":"The experiment demonstrates the theory.","zh-TW":"這個實驗證明了該理論。"},{"en":"Let me demonstrate how to use this tool.","zh-TW":"讓我示範如何使用這個工具。"}]', '{"noun":"demonstration","verb":"demonstrate"}', NULL, 4, 1930, 100),
(1931, 'demotion', '/dɪˈmoʊʃən/', 'noun', '{"zh-TW":["降職；貶職"],"en":["the reduction of an employee to a lower rank or position"]}', NULL, 'face demotion / voluntary demotion / demotion policy', '[{"en":"He accepted a demotion rather than relocating to another city.","zh-TW":"他接受了降職而不是搬到另一個城市。"},{"en":"Demotion without cause can constitute unfair treatment.","zh-TW":"無故降職可構成不公平對待。"}]', '{"verb":"demote","adjective":"demoted"}', NULL, 3, 1931, NULL),
(1932, 'demurrage', '/dɪˈmɜːrɪdʒ/', 'noun', '{"zh-TW":["滯期費"],"en":["charges for keeping a ship or container beyond the agreed time"]}', NULL, 'incur demurrage / pay demurrage / demurrage charges', '[{"en":"The company was charged demurrage for holding the container too long.","zh-TW":"公司因持有貨櫃過久而被收取滯期費。"},{"en":"Demurrage charges accumulated while the port was congested.","zh-TW":"港口擁堵期間滯期費不斷累積。"}]', NULL, NULL, 3, 1932, NULL),
(1933, 'demutualization', '/diːˌmjuːtʃuəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["去互助化；股份化"],"en":["the conversion of a mutual organization into a shareholder-owned company"]}', NULL, 'complete the demutualization / demutualization process', '[{"en":"The insurance cooperative underwent demutualization to access capital markets.","zh-TW":"保險合作社進行了去互助化以進入資本市場。"},{"en":"Demutualization distributes shares to existing members of the mutual company.","zh-TW":"去互助化將股份分配給互助公司的現有成員。"}]', '{"verb":"demutualize"}', NULL, 5, 1933, NULL),
(1934, 'denial', '/dɪˈnaɪəl/', 'noun', '{"zh-TW":["否認；拒絕"],"en":["a refusal to acknowledge something or to grant a request"]}', NULL, 'denial of service / denial of a claim / issue a denial', '[{"en":"The company issued a denial of the allegations in the press.","zh-TW":"公司向媒體發出了對指控的否認聲明。"},{"en":"The claim was met with a denial from the insurance company.","zh-TW":"索賠遭到保險公司拒絕。"}]', '{"verb":"deny","adjective":"denied"}', NULL, 2, 1934, NULL),
(1935, 'denotation', '/''diːnəʊˈteɪʃən/', 'noun', '{"zh-TW":["字面意義；明確含義"],"en":["the literal or primary meaning of a word, in contrast to its connotations"]}', NULL, 'literal denotation / denotation versus connotation', '[{"en":"The denotation of ''snake'' is a reptile, but its connotations often include deceit.","zh-TW":"「蛇」的字面意義是一種爬行動物，但其聯想意義常常包含欺騙。"},{"en":"Understanding both denotation and connotation is important for clear communication.","zh-TW":"理解字面意義和聯想意義對於清晰的溝通都很重要。"}]', '{"verb":"denote"}', NULL, 4, 1935, NULL),
(1936, 'denounce', '/''dɪˌnaʊns/', 'verb', '{"zh-TW":["譴責；公開批評"],"en":["to publicly declare to be wrong or evil; to condemn or criticize openly"]}', NULL, 'denounce a decision / publicly denounce / denounce as', '[{"en":"Human rights groups denounced the government''s use of excessive force.","zh-TW":"人權組織譴責政府使用過度武力。"},{"en":"She was the first to publicly denounce the corrupt practices within the organization.","zh-TW":"她是第一個公開批評組織內腐敗行為的人。"}]', '{"noun":"denunciation","adjective":"denunciatory"}', NULL, 3, 1936, NULL),
(1937, 'deny', '/dɪˈnaɪ/', 'verb', '{"zh-TW":["否認；拒絕"],"en":["to declare something untrue; to refuse","to refuse to admit the truth of","to refuse to give"]}', '{"prefix":{"text":"de-","meaning":"away (離開)"},"root":{"text":"ny","meaning":"say no (說不)"},"logic":"說不，即「否認」。"}', 'deny access/responsibility; deny the accusation / deny access / cannot deny', '[{"en":"He denied any involvement in the scandal.","zh-TW":"他否認與醜聞有任何關係。"},{"en":"Access was denied due to security reasons.","zh-TW":"由於安全原因，訪問被拒絕。"},{"en":"He denied all the accusations.","zh-TW":"他否認了所有指控。"},{"en":"They denied him access to the building.","zh-TW":"他們拒絕讓他進入大樓。"}]', '{"noun":"denial","verb":"deny"}', NULL, 1, 1937, NULL),
(1938, 'depart', '/dɪˈpɑːrt/', 'verb', '{"zh-TW":["離開；出發"],"en":["to leave, especially on a journey"]}', NULL, 'depart from', '[{"en":"The train departs at 8:00 AM.","zh-TW":"火車早上8點出發。"},{"en":"She departed from the original plan.","zh-TW":"她偏離了原來的計畫。"}]', '{"noun":"departure","verb":"depart"}', NULL, 2, 1938, NULL),
(1939, 'department', '/dɪˈpɑːrtmənt/', 'noun', '{"zh-TW":["部門；科系"],"en":["a division of a large organization or store"]}', '{"prefix":{"text":"de-","meaning":"apart (分開)"},"root":{"text":"part","meaning":"part (部分)"},"suffix":{"text":"-ment","meaning":"result (結果)"},"logic":"分開成各部分的結果，即「部門」。"}', 'department store / sales department', '[{"en":"The electronics department is on the second floor.","zh-TW":"電子產品部在二樓。"},{"en":"She works in the marketing department.","zh-TW":"她在行銷部門工作。"}]', '{"adjective":"departmental"}', NULL, 4, 1939, 22),
(1940, 'departure', '/dɪˈpɑːrtʃər/', 'noun', '{"zh-TW":["出發；離開"],"en":["the action of leaving a place"]}', NULL, 'departure time / departure gate', '[{"en":"The departure time has been moved up by one hour.","zh-TW":"出發時間提前了一小時。"},{"en":"Please proceed to the departure gate immediately.","zh-TW":"請立即前往登機門。"}]', '{"verb":"depart","adjective":"departing"}', NULL, 3, 1940, 23),
(1941, 'departure gate', '/''dɪˈpɑːtʃər ɡeɪt/', 'noun', '{"zh-TW":["登機門；出發閘口"],"en":["the designated location in an airport from which passengers board their flight"]}', NULL, 'proceed to departure gate / departure gate change / report to the departure gate', '[{"en":"Passengers should be at their departure gate at least thirty minutes before boarding.","zh-TW":"乘客應在登機前至少三十分鐘抵達登機門。"},{"en":"The departure gate for our flight was changed from Gate 14 to Gate 22.","zh-TW":"我們航班的登機門從14號更改為22號。"}]', NULL, NULL, 5, 1941, NULL),
(1942, 'departure lounge', '/dɪˈpɑːrtʃər laʊndʒ/', 'noun', '{"zh-TW":["候機廳；出發大廳"],"en":["the area in an airport where passengers wait before boarding"]}', NULL, 'wait in the departure lounge / departure lounge facilities', '[{"en":"Passengers gathered in the departure lounge before boarding.","zh-TW":"乘客在登機前聚集在候機廳。"},{"en":"The departure lounge has shops and restaurants.","zh-TW":"候機廳有商店和餐廳。"}]', NULL, NULL, 5, 1942, NULL),
(1943, 'depend', '/dɪˈpend/', 'verb', '{"zh-TW":["依賴；取決於"],"en":["to rely on; to be determined by","to rely on","to be determined by"]}', '{"prefix":{"text":"de-","meaning":"from (從)"},"root":{"text":"pend","meaning":"hang (懸掛)"},"logic":"懸掛在某物上依靠它，即「依賴」。"}', 'depend on/upon; depend on / it depends / depending on', '[{"en":"The outcome depends on several factors.","zh-TW":"結果取決於幾個因素。"},{"en":"You can depend on her to finish the task.","zh-TW":"你可以依賴她完成任務。"},{"en":"The outcome depends on many factors.","zh-TW":"結果取決於很多因素。"},{"en":"Children depend on their parents.","zh-TW":"孩子依賴他們的父母。"}]', '{"noun":"dependence/dependency","verb":"depend","adjective":"dependent/dependable","adjective2":"dependable"}', NULL, 2, 1943, NULL),
(1944, 'dependency', '/dɪˈpendənsi/', 'noun', '{"zh-TW":["依賴關係；相依性"],"en":["a task or factor that relies on another being completed first"]}', NULL, 'project dependency / identify dependencies / task dependency / manage dependencies', '[{"en":"The delay in design created a dependency issue for the developers.","zh-TW":"設計延遲為開發人員創造了依賴關係問題。"},{"en":"Critical dependencies must be identified early in project planning.","zh-TW":"關鍵依賴關係必須在項目規劃早期識別。"}]', '{"plural":"dependencies","adjective":"dependent"}', NULL, 4, 1944, NULL),
(1945, 'dependency injection', '/dɪˈpendənsi ɪnˈdʒekʃən/', 'noun', '{"zh-TW":["依賴注入"],"en":["a design pattern where objects receive dependencies rather than creating them"]}', NULL, 'implement dependency injection / dependency injection framework / dependency injection container', '[{"en":"Dependency injection makes code more testable and modular.","zh-TW":"依賴注入使代碼更易於測試和模組化。"},{"en":"Spring Framework uses dependency injection to manage object creation.","zh-TW":"Spring框架使用依賴注入來管理對象創建。"}]', NULL, NULL, 5, 1945, NULL),
(1946, 'deploy', '/dɪˈplɔɪ/', 'verb', '{"zh-TW":["部署；調配"],"en":["to put into use; also to distribute software or systems"]}', NULL, 'deploy resources / deploy software / deploy staff', '[{"en":"The IT team deployed the new system over the weekend.","zh-TW":"IT團隊在週末部署了新系統。"},{"en":"Additional staff were deployed to handle the holiday rush.","zh-TW":"調配了額外人員處理節假日的業務高峰。"}]', '{"noun":"deployment","adjective":"deployed"}', NULL, 2, 1946, 735),
(1947, 'deployment', '/dɪˈplɔɪmənt/', 'noun', '{"zh-TW":["部署；實施"],"en":["the process of making a system, software, or plan operational"]}', NULL, 'software deployment / deployment plan / production deployment', '[{"en":"The deployment of the new system went smoothly over the weekend.","zh-TW":"新系統的部署在週末順利完成。"},{"en":"A rollback plan was prepared in case the deployment failed.","zh-TW":"準備了回滾計劃以防部署失敗。"}]', '{"verb":"deploy","adjective":"deployed"}', NULL, 4, 1947, 542),
(1948, 'deposit', '/dɪˈpɑːzɪt/', 'noun / verb', '{"zh-TW":["存款；押金；存放"],"en":["money placed in a bank; to put money into an account"]}', NULL, 'make a deposit', '[{"en":"I need to make a deposit at the bank.","zh-TW":"我需要去銀行存款。"},{"en":"A deposit of $500 is required.","zh-TW":"需要500美元的押金。"}]', '{"noun":"deposit","verb":"deposit"}', NULL, 3, 1948, 329),
(1949, 'deposit account', '/dɪˈpɒzɪt əˈkaʊnt/', 'noun', '{"zh-TW":["存款帳戶；定期帳戶"],"en":["a bank account that earns interest on deposited funds"]}', NULL, 'open a deposit account / deposit account interest rate', '[{"en":"The company moved surplus funds into a high-interest deposit account.","zh-TW":"公司將盈餘資金轉移到高利息存款帳戶。"},{"en":"A deposit account is suitable for funds not needed for daily transactions.","zh-TW":"存款帳戶適合不需要日常交易的資金。"}]', NULL, NULL, 5, 1949, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1950, 'deposition', '/ˌdepəˈzɪʃən/', 'noun', '{"zh-TW":["證詞；書面詞供"],"en":["oral testimony given under oath outside of court, recorded for use in proceedings"]}', NULL, 'take a deposition / witness deposition / deposition transcript', '[{"en":"The attorney took a deposition from the key witness before trial.","zh-TW":"律師在審判前從關鍵證人那裡取得了書面詞供。"},{"en":"Depositions are a key discovery tool in civil litigation.","zh-TW":"書面詞供是民事訴訟中的關鍵取證工具。"}]', '{"verb":"depose"}', NULL, 4, 1950, NULL),
(1951, 'depreciate', '/dɪˈpriːʃieɪt/', 'verb', '{"zh-TW":["貶值；折舊"],"en":["to decrease in value over time"]}', NULL, 'depreciate in value', '[{"en":"The car depreciated quickly after purchase.","zh-TW":"這輛車購買後迅速貶值。"},{"en":"Equipment depreciates over its useful life.","zh-TW":"設備在其使用壽命內折舊。"}]', '{"noun":"depreciation","verb":"depreciate"}', NULL, 4, 1951, 666),
(1952, 'depreciated cost', '/dɪˈpriːʃɪeɪtɪd kɒst/', 'noun', '{"zh-TW":["已折舊成本；帳面價值"],"en":["the remaining book value of an asset after accumulated depreciation"]}', NULL, 'calculate depreciated cost / asset at depreciated cost', '[{"en":"The machinery is recorded at its depreciated cost of $40000.","zh-TW":"機械以其4萬元的已折舊成本記錄。"},{"en":"Depreciated cost reflects the value remaining after accounting for wear.","zh-TW":"已折舊成本反映了計算磨損後剩餘的價值。"}]', NULL, NULL, 5, 1952, NULL),
(1953, 'depreciation', '/dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["折舊；貶值"],"en":["a decrease in value over time"]}', NULL, 'asset depreciation / annual depreciation', '[{"en":"We account for annual depreciation of equipment.","zh-TW":"我們計算設備的年度折舊。"},{"en":"Currency depreciation affects import costs.","zh-TW":"貨幣貶值影響進口成本。"}]', '{"noun":"depreciation","verb":"depreciate"}', NULL, 4, 1953, 775),
(1954, 'depreciation charge', '/dɪˌpriːʃiˈeɪʃən tʃɑːrdʒ/', 'noun', '{"zh-TW":["折舊費用"],"en":["the accounting expense recording the annual reduction in an asset''s value"]}', NULL, 'record a depreciation charge / depreciation charge calculation', '[{"en":"The annual depreciation charge for machinery is $50000.","zh-TW":"機械的年度折舊費用為5萬元。"},{"en":"Depreciation charges reduce taxable income but are non-cash expenses.","zh-TW":"折舊費用降低了應稅所得，但屬於非現金費用。"}]', NULL, NULL, 5, 1954, NULL),
(1955, 'depreciation expense', '/dɪˌpriːʃiˈeɪʃən ɪkˈspens/', 'noun', '{"zh-TW":["折舊費用"],"en":["the portion of an asset value recognized as an expense each year"]}', NULL, 'record depreciation expense / reduce depreciation expense', '[{"en":"Depreciation expense reduced the company operating income.","zh-TW":"折舊費用降低了公司的營業收入。"},{"en":"An accountant calculates the annual depreciation expense for each asset.","zh-TW":"會計師計算每項資產的年度折舊費用。"}]', NULL, NULL, 5, 1955, NULL),
(1956, 'depreciation rate', '/dɪˌpriːʃiˈeɪʃən reɪt/', 'noun', '{"zh-TW":["折舊率"],"en":["the percentage of an asset''s value written off each year"]}', NULL, 'set the depreciation rate / straight-line depreciation rate', '[{"en":"The depreciation rate for machinery is set at 20% per annum.","zh-TW":"機械的折舊率設定為每年20%。"},{"en":"A higher depreciation rate reduces taxable income in early years.","zh-TW":"較高的折舊率在前幾年降低了應稅收入。"}]', NULL, NULL, 5, 1956, NULL),
(1957, 'depressed', '/dɪˈprest/', 'adjective', '{"zh-TW":["沮喪的；憂鬱的"],"en":["in a state of unhappiness"]}', '{"prefix":{"text":"de-","meaning":"down (向下)"},"root":{"text":"press","meaning":"press (壓)"},"suffix":{"text":"-ed","meaning":"state (狀態)"},"logic":"被向下壓的狀態，即「沮喪的」。"}', 'feel depressed / clinically depressed', '[{"en":"He felt depressed after losing his job.","zh-TW":"失業後他感到很沮喪。"},{"en":"If you feel depressed, seek professional help.","zh-TW":"如果你感到憂鬱，請尋求專業協助。"}]', '{"noun":"depression","verb":"depress","adjective":"depressing"}', NULL, 3, 1957, NULL),
(1958, 'deputy', '/ˈdepjʊti/', 'noun', '{"zh-TW":["副職；代理人"],"en":["a person second in command or authorized to act for a senior"]}', NULL, 'appoint a deputy / act as deputy / deputy director', '[{"en":"The deputy was authorized to sign contracts in the director''s absence.","zh-TW":"副職在主任缺席時被授權簽署合約。"},{"en":"She served as deputy CFO before her promotion.","zh-TW":"她在晉升前擔任副財務長。"}]', '{"adjective":"deputy","plural":"deputies"}', NULL, 2, 1958, NULL),
(1959, 'deregulation', '/diːˌrɛɡjʊˈleɪʃən/', 'noun', '{"zh-TW":["解除管制；放鬆管制"],"en":["the removal of government regulations from an industry"]}', NULL, 'support deregulation / financial deregulation', '[{"en":"Deregulation of the airline industry led to lower ticket prices.","zh-TW":"航空業的解除管制導致機票價格下降。"},{"en":"The government initiated deregulation to stimulate competition.","zh-TW":"政府啟動解除管制以刺激競爭。"}]', '{"verb":"deregulate"}', NULL, 4, 1959, NULL),
(1960, 'derivative', '/dɪˈrɪvətɪv/', 'noun', '{"zh-TW":["衍生性金融商品"],"en":["a financial instrument whose value is based on an underlying asset"]}', NULL, 'financial derivative / derivative contract / trade derivatives', '[{"en":"Derivatives can be used to hedge against currency risk.","zh-TW":"衍生性商品可用於對沖貨幣風險。"},{"en":"The bank''s exposure to derivatives raised regulatory concerns.","zh-TW":"銀行對衍生性商品的敞口引發了監管擔憂。"}]', '{"adjective":"derivative"}', NULL, 4, 1960, 776),
(1961, 'derivatives market', '/dɪˈrɪvətɪvz ˈmɑːrkɪt/', 'noun', '{"zh-TW":["衍生品市場"],"en":["a financial market for instruments whose value is derived from underlying assets"]}', NULL, 'trade in the derivatives market / derivatives market regulation', '[{"en":"Companies hedge currency risk by trading in the derivatives market.","zh-TW":"公司通過在衍生品市場交易來對沖貨幣風險。"},{"en":"The derivatives market includes futures, options, and swap contracts.","zh-TW":"衍生品市場包括期貨、期權和互換合約。"}]', NULL, NULL, 5, 1961, NULL),
(1962, 'derive', '/dɪˈraɪv/', 'verb', '{"zh-TW":["源自；獲得"],"en":["to obtain from a source; to originate"]}', NULL, 'derive from', '[{"en":"The word derives from Latin.","zh-TW":"這個詞源自拉丁語。"},{"en":"We derive great satisfaction from our work.","zh-TW":"我們從工作中獲得極大的滿足感。"}]', '{"noun":"derivation/derivative","verb":"derive"}', NULL, 2, 1962, NULL),
(1963, 'dermatology', '/ˌdɜːrmɪˈtɒlədʒi/', 'noun', '{"zh-TW":["皮膚科；皮膚病學"],"en":["the branch of medicine dealing with skin conditions"]}', NULL, 'dermatology clinic / consult a dermatologist', '[{"en":"She visited the dermatology clinic for a skin allergy.","zh-TW":"她前往皮膚科診所治療皮膚過敏。"},{"en":"Dermatology treatments range from acne care to cancer screening.","zh-TW":"皮膚科治療範圍從痤瘡護理到癌症篩查。"}]', '{"noun":"dermatologist","adjective":"dermatological"}', NULL, 4, 1963, NULL),
(1964, 'desalination', '/dɪˌsælɪˈneɪʃən/', 'noun', '{"zh-TW":["海水淡化"],"en":["the removal of salt from seawater to produce fresh water"]}', NULL, 'desalination plant / desalination technology / water desalination', '[{"en":"Desalination provides fresh water in water-scarce coastal regions.","zh-TW":"海水淡化為缺水的沿海地區提供淡水。"},{"en":"Advanced desalination technology is becoming more energy-efficient.","zh-TW":"先進的海水淡化技術正在變得更加節能。"}]', '{"verb":"desalinate","adjective":"desalinated"}', NULL, 4, 1964, NULL),
