(1977, 'destination', '/ˌdestɪˈneɪʃən/', 'noun', '{"zh-TW":["目的地"],"en":["the place to which someone is going"]}', '{"root":{"text":"destin","meaning":"determine (決定)"},"suffix":{"text":"-ation","meaning":"place (地方)"},"logic":"決定要去的地方，即「目的地」。"}', 'tourist/popular destination; popular destination / final destination / travel destination', '[{"en":"We arrived at our destination on time.","zh-TW":"我們準時到達了目的地。"},{"en":"Paris is a popular tourist destination.","zh-TW":"巴黎是熱門的旅遊目的地。"},{"en":"Paris is a popular tourist destination.","zh-TW":"巴黎是熱門旅遊目的地。"},{"en":"We arrived at our destination at noon.","zh-TW":"我們中午抵達目的地。"}]', '{"noun":"destination"}', NULL, 4, 1977, NULL),
