(1981, 'detect', '/dɪˈtekt/', 'verb', '{"zh-TW":["偵測；發現"],"en":["to discover or notice something","to discover the presence of something"]}', '{"prefix":{"text":"de-","meaning":"away (除去)"},"root":{"text":"tect","meaning":"cover (覆蓋)"},"logic":"把覆蓋物移除而發現，即「偵測」。"}', 'detect a problem/error; detect a problem / detect changes', '[{"en":"The system detected an error in the data.","zh-TW":"系統偵測到資料中的錯誤。"},{"en":"Cancer can be treated if detected early.","zh-TW":"癌症如果早期發現可以治療。"},{"en":"The sensor can detect small changes in temperature.","zh-TW":"感測器能偵測到微小的溫度變化。"},{"en":"Police detected traces of the substance.","zh-TW":"警方偵測到該物質的痕跡。"}]', '{"noun":"detection/detector","verb":"detect","adjective":"detectable","noun2":"detector"}', NULL, 2, 1981, 331),
(1982, 'deter', '/dɪˈtɜːr/', 'verb', '{"zh-TW":["阻止；嚇阻"],"en":["to discourage someone from doing something through fear of consequences"]}', NULL, 'deter fraud / deter misconduct / act as a deterrent', '[{"en":"Strong penalties deter companies from cutting safety corners.","zh-TW":"嚴厲的懲罰阻止公司在安全方面偷工減料。"},{"en":"Regular audits deter fraudulent activity in financial reporting.","zh-TW":"定期審計阻止財務報告中的詐欺行為。"}]', '{"noun":"deterrent","adjective":"deterred"}', NULL, 2, 1982, NULL),
