(1984, 'determinant', '/dɪˈtɜːrmɪnənt/', 'noun', '{"zh-TW":["決定因素"],"en":["a factor that decides or controls an outcome"]}', NULL, 'key determinant / major determinant / social determinant', '[{"en":"Education is widely recognized as a key determinant of economic mobility.","zh-TW":"教育被廣泛認為是經濟流動性的關鍵決定因素。"},{"en":"Social determinants of health include income, housing, and access to nutrition.","zh-TW":"健康的社會決定因素包括收入、住房和獲得營養的機會。"}]', '{"adjective":"determinant","verb":"determine"}', NULL, 4, 1984, NULL),
(1985, 'determine', '/dɪˈtɜːrmɪn/', 'verb', '{"zh-TW":["決定；確定"],"en":["to find out; to be the cause of","to find out or establish exactly"]}', NULL, 'determine the cause/outcome; determine the cause / determined to', '[{"en":"We need to determine the cause of the problem.","zh-TW":"我們需要確定問題的原因。"},{"en":"Your score determines your final grade.","zh-TW":"你的分數決定你的最終成績。"},{"en":"We need to determine the cause.","zh-TW":"我們需要確定原因。"},{"en":"She''s determined to succeed.","zh-TW":"她決心要成功。"}]', '{"noun":"determination","verb":"determine","adjective":"determined"}', NULL, 3, 1985, 103),
