(1987, 'determinism', '/dɪˈtɜːrmɪnɪzəm/', 'noun', '{"zh-TW":["決定論"],"en":["the doctrine that all events are determined completely by prior causes"]}', NULL, 'hard determinism / technological determinism / economic determinism', '[{"en":"Technological determinism argues that technology shapes social change.","zh-TW":"技術決定論認為技術塑造社會變革。"},{"en":"The debate between free will and determinism has occupied philosophers for centuries.","zh-TW":"自由意志與決定論之間的辯論已讓哲學家糾纏了幾個世紀。"}]', '{"adjective":"deterministic","noun":"determinist"}', NULL, 4, 1987, NULL),
