(1989, 'detour', '/''diːtʊər/', 'noun', '{"zh-TW":["繞行；迂迴路線"],"en":["a long or roundabout route taken to avoid something or to visit somewhere along the way"]}', NULL, 'take a detour / scenic detour / road detour', '[{"en":"We made a detour to visit the ancient ruins on our way to the coast.","zh-TW":"我們繞道參觀了通往海岸途中的古遺跡。"},{"en":"The road construction forced us to take a ten-mile detour.","zh-TW":"道路施工迫使我們繞行十英里的迂迴路線。"}]', NULL, NULL, 2, 1989, NULL),
