(1991, 'devastating', '/ˈdevəsteɪtɪŋ/', 'adjective', '{"zh-TW":["毀滅性的"],"en":["causing severe damage or destruction"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"vast","meaning":"empty/waste (荒廢)"},"suffix":{"text":"-ating","meaning":"causing (造成)"},"logic":"造成完全荒廢的，即「毀滅性的」。"}', 'devastating effect / devastating news', '[{"en":"The hurricane had a devastating impact on the town.","zh-TW":"颶風對城鎮造成了毀滅性的影響。"},{"en":"The news was devastating for the family.","zh-TW":"這個消息對這家人來說是毀滅性的打擊。"}]', '{"verb":"devastate","noun":"devastation"}', NULL, 4, 1991, NULL),
